package com.mumin.pisi;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

public class MainActivity extends Activity{
 static final String P="pisi_data"; final ArrayList<JSONObject> notes=new ArrayList<>(),tasks=new ArrayList<>(); LinearLayout body,nav; int tab=0,ink,muted,accent,cream,surface,line;
 public void onCreate(Bundle b){super.onCreate(b); ink=c(R.color.pisi_ink);muted=c(R.color.pisi_muted);accent=c(R.color.pisi_accent);cream=c(R.color.pisi_cream);surface=c(R.color.pisi_surface);line=c(R.color.pisi_line);getWindow().setStatusBarColor(cream);getWindow().setNavigationBarColor(surface);load();shell();home();}
 int c(int id){return getColor(id);} int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);} TextView tx(String s,int z,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextColor(ink);v.setTextSize(z);v.setTypeface(null,bold?1:0);return v;}
 GradientDrawable bg(int fill,int stroke,int r){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(r));g.setStroke(dp(1),stroke);return g;} LinearLayout card(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(dp(16),dp(14),dp(16),dp(14));x.setBackground(bg(surface,line,18));return x;}
 EditText input(String hint,boolean one){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(ink);e.setHintTextColor(muted);e.setSingleLine(one);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(bg(surface,line,14));return e;} Button btn(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:ink);b.setBackground(bg(primary?accent:Color.TRANSPARENT,primary?accent:Color.TRANSPARENT,14));return b;} LinearLayout.LayoutParams mp(int bottom){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(bottom);return p;}
 void shell(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(cream);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(14),dp(20),dp(12));root.addView(body,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setGravity(17);nav.setBackgroundColor(surface);root.addView(nav,new LinearLayout.LayoutParams(-1,dp(70)));setContentView(root);nav();}
 void nav(){nav.removeAllViews();String[] a={getString(R.string.home),getString(R.string.notes),getString(R.string.tasks),getString(R.string.search),getString(R.string.settings)};String[] i={"⌂","▤","✓","⌕","⚙"};for(int n=0;n<5;n++){final int k=n;LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setGravity(17);TextView q=tx(i[n],22,n==tab);q.setTextColor(n==tab?accent:muted);TextView t=tx(a[n],11,n==tab);t.setTextColor(n==tab?accent:muted);x.addView(q);x.addView(t);x.setOnClickListener(v->{tab=k;if(k==0)home();if(k==1)notes();if(k==2)tasks();if(k==3)search();if(k==4)settings();nav();});nav.addView(x,new LinearLayout.LayoutParams(0,-1,1));}}
 void clear(){body.removeAllViews();nav.setVisibility(View.VISIBLE);} void head(String a,String b){body.addView(tx(a,27,true));TextView s=tx(b,13,false);s.setTextColor(muted);body.addView(s,mp(16));}
 void home(){tab=0;clear();head(greet(),getString(R.string.offline_message));LinearLayout q=card();q.addView(tx(getString(R.string.quick_note),18,true));EditText e=input(getString(R.string.content),false);e.setMinLines(3);q.addView(e,mp(8));Button save=btn(getString(R.string.save),true);save.setOnClickListener(v->{String z=e.getText().toString().trim();if(z.isEmpty())return;addNote(z.split("\\R",2)[0],z);home();});q.addView(save);body.addView(q,mp(14));body.addView(tx(getString(R.string.recent_notes),18,true),mp(10));for(int n=0;n<Math.min(3,notes.size());n++)body.addView(noteRow(notes.get(n)),mp(8));if(notes.isEmpty())body.addView(empty(getString(R.string.empty_notes)));}
 void notes(){tab=1;clear();head(getString(R.string.notes),getString(R.string.recent_notes));Button b=btn(getString(R.string.new_note),true);b.setOnClickListener(v->editor(null));body.addView(b,mp(12));ScrollView s=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);for(JSONObject n:notes)l.addView(noteRow(n),mp(8));if(notes.isEmpty())l.addView(empty(getString(R.string.empty_notes)));s.addView(l);body.addView(s,new LinearLayout.LayoutParams(-1,0,1));}
 View noteRow(JSONObject n){LinearLayout x=card();x.addView(tx(n.optString("title",getString(R.string.new_note)),17,true));TextView p=tx(shorten(n.optString("body")),14,false);p.setTextColor(muted);x.addView(p);x.setOnClickListener(v->editor(n));return x;}
 void editor(JSONObject old){clear();nav.setVisibility(View.GONE);LinearLayout bar=new LinearLayout(this);Button back=btn("‹",false);bar.addView(back,new LinearLayout.LayoutParams(dp(52),dp(48)));bar.addView(tx(old==null?getString(R.string.new_note):getString(R.string.edit),20,true),new LinearLayout.LayoutParams(0,-2,1));Button save=btn(getString(R.string.save),true);bar.addView(save);body.addView(bar,mp(10));EditText title=input(getString(R.string.title),true),content=input(getString(R.string.content),false);if(old!=null){title.setText(old.optString("title"));content.setText(old.optString("body"));}content.setGravity(48);body.addView(title,mp(10));body.addView(content,new LinearLayout.LayoutParams(-1,0,1));back.setOnClickListener(v->notes());save.setOnClickListener(v->{String a=title.getText().toString().trim(),z=content.getText().toString().trim();if(a.isEmpty()&&!z.isEmpty())a=z.split("\\R",2)[0];if(old==null)addNote(a,z);else try{old.put("title",a);old.put("body",z);old.put("time",System.currentTimeMillis());save();}catch(Exception ignored){}notes();});if(old!=null){Button del=btn(getString(R.string.delete),false);del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage(getString(R.string.delete)+"?").setNegativeButton(getString(R.string.cancel),null).setPositiveButton(getString(R.string.delete),(d,w)->{notes.remove(old);save();notes();}).show());body.addView(del);}}
 void tasks(){tab=2;clear();head(getString(R.string.tasks),getString(R.string.today));Button add=btn(getString(R.string.new_task),true);add.setOnClickListener(v->taskDialog());body.addView(add,mp(12));ScrollView s=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);for(JSONObject t:tasks)l.addView(taskRow(t),mp(8));if(tasks.isEmpty())l.addView(empty(getString(R.string.empty_tasks)));s.addView(l);body.addView(s,new LinearLayout.LayoutParams(-1,0,1));}
 View taskRow(JSONObject t){LinearLayout x=card();x.setOrientation(LinearLayout.HORIZONTAL);x.setGravity(16);CheckBox c=new CheckBox(this);c.setChecked(t.optBoolean("done"));c.setOnCheckedChangeListener((v,z)->{try{t.put("done",z);save();}catch(Exception ignored){}});x.addView(c);TextView a=tx(t.optString("title"),16,!t.optBoolean("done"));x.addView(a,new LinearLayout.LayoutParams(0,-2,1));Button d=btn("×",false);d.setOnClickListener(v->{tasks.remove(t);save();tasks();});x.addView(d,new LinearLayout.LayoutParams(dp(46),dp(46)));return x;}
 void taskDialog(){EditText e=input(getString(R.string.new_task),true);FrameLayout f=new FrameLayout(this);f.setPadding(dp(20),0,dp(20),0);f.addView(e);new AlertDialog.Builder(this).setTitle(getString(R.string.new_task)).setView(f).setNegativeButton(getString(R.string.cancel),null).setPositiveButton(getString(R.string.add),(d,w)->{String z=e.getText().toString().trim();if(!z.isEmpty()){JSONObject o=new JSONObject();try{o.put("id",UUID.randomUUID());o.put("title",z);o.put("done",false);tasks.add(0,o);save();tasks();}catch(Exception ignored){}}}).show();}
 void search(){tab=3;clear();head(getString(R.string.search),getString(R.string.search_hint));EditText e=input(getString(R.string.search_hint),true);body.addView(e,mp(10));ScrollView s=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);s.addView(l);body.addView(s,new LinearLayout.LayoutParams(-1,0,1));e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence x,int a,int b,int c){}public void onTextChanged(CharSequence x,int a,int b,int c){l.removeAllViews();String q=x.toString().toLowerCase();for(JSONObject n:notes)if((n.optString("title")+n.optString("body")).toLowerCase().contains(q)&&!q.isEmpty())l.addView(noteRow(n),mp(8));for(JSONObject t:tasks)if(t.optString("title").toLowerCase().contains(q)&&!q.isEmpty())l.addView(taskRow(t),mp(8));}public void afterTextChanged(Editable x){}});}
 void settings(){tab=4;clear();head(getString(R.string.settings),getString(R.string.offline_message));LinearLayout x=card();ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_pisi);x.addView(logo,new LinearLayout.LayoutParams(dp(86),dp(86)));x.addView(tx("Pisi",28,true));TextView z=tx(notes.size()+" "+getString(R.string.notes)+" · "+tasks.size()+" "+getString(R.string.tasks),14,false);z.setTextColor(muted);x.addView(z);body.addView(x);}
 View empty(String s){TextView t=tx(s,15,false);t.setTextColor(muted);t.setGravity(17);t.setPadding(0,dp(40),0,dp(40));return t;} String shorten(String s){s=s.replace('\n',' ');return s.length()>100?s.substring(0,100)+"…":s;} String greet(){int h=Calendar.getInstance().get(11);boolean tr=Locale.getDefault().getLanguage().equals("tr");return tr?(h<12?"Günaydın":h<18?"İyi günler":"İyi akşamlar"):(h<12?"Good morning":h<18?"Good afternoon":"Good evening");}
 void addNote(String a,String z){JSONObject o=new JSONObject();try{o.put("id",UUID.randomUUID());o.put("title",a);o.put("body",z);o.put("time",System.currentTimeMillis());notes.add(0,o);save();}catch(Exception ignored){}} void load(){SharedPreferences p=getSharedPreferences(P,0);try{JSONArray a=new JSONArray(p.getString("notes","[]"));for(int i=0;i<a.length();i++)notes.add(a.getJSONObject(i));JSONArray b=new JSONArray(p.getString("tasks","[]"));for(int i=0;i<b.length();i++)tasks.add(b.getJSONObject(i));}catch(Exception ignored){}} void save(){JSONArray a=new JSONArray(),b=new JSONArray();for(JSONObject o:notes)a.put(o);for(JSONObject o:tasks)b.put(o);getSharedPreferences(P,0).edit().putString("notes",a.toString()).putString("tasks",b.toString()).apply();}
}
